import resetPwd from "@/views/user/info.vue";
import { remindList, reminduserSave } from "@/api/page/index";
import {mapGetters} from "vuex";
import tags from "./tags";
import top from "./top/";
import sidebar from "./sidebar/";
import admin from "@/util/admin";
import {validatenull} from "@/util/validate";
import {calcDate} from "@/util/date.js";
import {getStore} from "@/util/store.js";
import {updatePassword} from "@/api/system/user";

export default {
  components: {
    top,
    tags,
    sidebar,
    resetPwd
  },
  name: "index",
  data() {
    return {
      queryParams: {

      },
      firstVisible: false,

      drawer: false,
      remindList: [],


      //刷新token锁
      refreshLock: false,
      //刷新token的时间
      refreshTime: "",
      refreshTag: false,
    };
  },
  watch: {
    $route(to, from) {
      this.$nextTick(() => {
        if (to.meta.keepAlive) {
          let keepView = this.$refs.aliveRtView;
          if (keepView) {
            this.$store.state.common.keepAliveNodes[keepView.$vnode.componentInstance.$route.path] = keepView;
          }
        }
      })
    },
  },
  created() {
    //实时检测刷新token
    //this.refreshToken();

    setTimeout(() => {
      if( this.userDetail.isLogin === 0 ){
        this.firstVisible=true
      }
    }, 200);
  },
  mounted() {
    this.getRemindList()
    this.init();
    this.$EventBus.$on('tagRefresh', () => {
      this.refreshTag = true;
      this.$nextTick(() => {
        this.refreshTag = false;
      })
    });
  },
  computed: {
    ...mapGetters(["isLock", "isCollapse", "website", "userInfo", "userDetail"]),
    currentPath() {
      return this.$route.path == "/wel/index"
    }
  },
  props: [],
  methods: {
    handleSubmit(form) {
      if (form.newPassword && form.newPassword1){
        updatePassword(form.oldPassword, form.newPassword, form.newPassword1,this.userInfo.userId).then(res => {
          if (res.success) {
            this.firstVisible = false
            this.$message({
              type: "success",
              message: "修改密码成功!"
            });
            setTimeout(() => {
              location.reload()
            }, 300);

            // this.$store.dispatch("LogOut").then(() => {
            //   this.$router.push({ path: "/login" });
            // });
          } else {
            this.$message({
              type: "error",
              message: res.msg
            });
          }

        })
      }else {
        this.$message({
          type: "warning",
          message: "请输入密码!"
        });
      }
    },

    handleClose(done){
      // this.firstVisible=false
    },
    handleDrawer(item){
      reminduserSave({
        remindId: item.id,
        userId: this.userInfo.userId
      }).then(res=>{
        this.getRemindList()
      })
    },
    getRemindList(){
      remindList().then(res=>{
        this.remindList = res.data
      })
    },
    showCollapse() {
      this.$store.commit("SET_COLLAPSE");
    },
    // 屏幕检测
    init() {
      this.$store.commit("SET_SCREEN", admin.getScreen());
      window.onresize = () => {
        setTimeout(() => {
          this.$store.commit("SET_SCREEN", admin.getScreen());
        }, 0);
      };
    },
    // 定时检测一次token
    refreshToken() {
      this.refreshTime = setInterval(() => {
        const token = getStore({
          name: "token",
          debug: true
        }) || {};
        const date = calcDate(token.datetime, new Date().getTime());
        if (validatenull(date)) return;
        if (date.seconds >= this.website.tokenTime && !this.refreshLock) {
          this.refreshLock = true;
          this.$store
            .dispatch("RefreshToken")
            .then(() => {
              this.refreshLock = false;
            })
            .catch(() => {
              this.refreshLock = false;
              clearInterval(this.refreshTime);
            });
        }
      }, 1000);
    },
  }
};
